-- 019_insert_valencia_centers.sql
-- Inserta los 162 centros de educacion infantil (0-3 anos) de Valencia
-- investigados y humanizados en este sprint (139 guarderia + 23 escuela-infantil:
-- 15 publicos [11 municipales del Ajuntament de Valencia + 4 de la Generalitat
-- Valenciana] + 8 privados concertados).
-- Fuente: data/enrichment/valencia-centers.json (generado 2026-07-11T12:37:29.538Z).
-- Fuente primaria de datos: dadesobertes.gva.es (Generalitat Valenciana),
-- complementada con scraping de fichas oficiales para los 11 centros
-- municipales (email institucional, gestion directa/indirecta, horario
-- cuando estaba confirmado). Ver docs/data-sources-valencia.md.
--
-- A diferencia de Madrid/Barcelona, ninguna fuente disponible para Valencia
-- incluye distrito o barrio (ver limitacion documentada en
-- docs/data-sources-valencia.md), por lo que district/neighborhood_barrio
-- quedan NULL en los 162 centros.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por
-- RLS hasta cambiarlos a 'published' manualmente, igual que se hizo con
-- Madrid y Barcelona).
-- No toca ningun centro de Madrid ni Barcelona. No borra ni modifica filas
-- existentes (upsert por slug: si un slug ya existe se actualiza, no se
-- duplica).
-- Generado: 2026-07-11. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "valencia" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('valencia', 'Valencia', 'Valencia', 'Comunitat Valenciana')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('los-angeles-valencia', 'Los Ángeles', 'escuela-infantil', 'concertado', 'Carrer Joaquin Costa 10', '46005', 'valencia', 'Valencia', NULL, NULL, NULL, 39.46658, -0.36772, '963325044', NULL, 'https://www.ceice.gva.es/web/centros-docentes/ficha-centro?codi=46009666', 0, 36, NULL, '{}'::text[], 'Los Ángeles es un centro privado de educación infantil situado en el carrer Joaquín Costa 10, en Valencia. Figura en el Registre de Centres Docents de la Generalitat Valenciana en régimen privado concertado, atendiendo a niños del primer ciclo de 0 a 3 años. Recomendamos contactar directamente con el centro para conocer plazas, horarios y servicios disponibles.', 'En el carrer Joaquín Costa 10 de Valencia se encuentra Los Ángeles, un centro de educación infantil de titularidad privada que opera en régimen concertado según consta en el Registre de Centres Docents de la Generalitat Valenciana. Su denominación genérica oficial es la de centro privado de educación infantil, dedicado al primer ciclo de esta etapa educativa, es decir, a niños de entre 0 y 3 años.

La entidad titular del centro es MAMEMIMOMU, SLU, responsable de su gestión ante la administración autonómica. El régimen concertado implica que el centro mantiene un acuerdo con la Generalitat Valenciana, aunque esta ficha no puede precisar en qué condiciones concretas se aplica dicho concierto.

No disponemos de datos verificados sobre servicios como comedor, horario ampliado o idiomas, ya que el registro oficial consultado no los recoge para este tipo de centros. Por eso recomendamos confirmar directamente con Los Ángeles estos aspectos antes de solicitar plaza, ya sea por teléfono o pidiendo información actualizada al propio centro.', '{}'::text[], '[{"question":"¿Dónde está ubicado Los Ángeles?","answer":"El centro se encuentra en el carrer Joaquín Costa 10, código postal 46005, en Valencia."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro privado que opera en régimen concertado con la Generalitat Valenciana."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 963325044 para solicitar información sobre plazas y servicios."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del Registre de Centres Docents de la Generalitat Valenciana. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://dadesobertes.gva.es/va/dataset/edu-centros', '{}'::text[], '2026-07-11'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('concha-espina-i-valencia', 'Concha Espina i', 'escuela-infantil', 'concertado', 'Carrer Carters 22-24', '46017', 'valencia', 'Valencia', NULL, NULL, NULL, 39.4537, -0.388287, '963571411', NULL, 'https://www.ceice.gva.es/web/centros-docentes/ficha-centro?codi=46010061', 0, 36, NULL, ARRAY['comedor','catering']::text[], 'Situado en el carrer Carters 22-24 de Valencia, Concha Espina I es un centro de educación infantil de titularidad privada en régimen concertado. Según el Registre de Centres Docents de la Generalitat Valenciana, atiende el primer ciclo de la etapa infantil (0-3 años). Se recomienda contactar con el centro para conocer horarios, servicios y disponibilidad de plazas.', 'Concha Espina I figura en el Registre de Centres Docents de la Generalitat Valenciana como centro privado de educación infantil en régimen concertado, con dirección en el carrer Carters 22-24, código postal 46017, Valencia. Al tratarse de un centro de primer ciclo, atiende a niños de 0 a 3 años.

La titularidad corresponde a la empresa Concha Espina, SL, entidad que figura como responsable ante la Generalitat Valenciana. El régimen concertado distingue a este centro de otras guarderías puramente privadas, aunque esta ficha no puede detallar el alcance concreto del concierto.

Como ocurre con buena parte de los centros de este tipo, el registro oficial no incluye información sobre comedor, cocina propia, horario ampliado o programas de idiomas, de modo que no podemos confirmar estos servicios aquí. Si buscas más detalles sobre el proyecto educativo o las plazas disponibles, lo más fiable es contactar directamente con el centro por teléfono.', '{}'::text[], '[{"question":"¿Dónde se encuentra Concha Espina I?","answer":"Está en el carrer Carters 22-24, código postal 46017, en Valencia."},{"question":"¿A qué edades atiende?","answer":"Atiende a niños del primer ciclo de educación infantil, de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro privado en régimen concertado, según el registro autonómico."},{"question":"¿Cuál es la mejor forma de contactar?","answer":"El centro puede contactarse en el teléfono 963571411."},{"question":"¿Está verificada esta ficha?","answer":"Los datos proceden del Registre de Centres Docents de la Generalitat Valenciana. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://dadesobertes.gva.es/va/dataset/edu-centros', '{}'::text[], '2026-07-11'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('ciudad-jardin-valencia', 'Ciudad Jardín', 'guarderia', 'privado', 'Carrer José de Orga 4', '46022', 'valencia', 'Valencia', NULL, NULL, NULL, 39.469603, -0.344921, '963725768', NULL, 'https://www.ceice.gva.es/web/centros-docentes/ficha-centro?codi=46013013', 0, 36, NULL, ARRAY['bilingue','ingles','cocina-propia','actividades-extraescolares','musica','verano-campamentos']::text[], 'Ciudad Jardín es una guardería privada ubicada en el carrer José de Orga 4, en Valencia (46022). Consta en el Registre de Centres Docents de la Generalitat Valenciana como centro de educación infantil de titularidad privada. Antes de solicitar información sobre plazas, horarios o servicios, recomendamos ponerse en contacto directamente con el centro.', 'Con dirección en el carrer José de Orga 4 de Valencia, código postal 46022, Ciudad Jardín aparece registrada como centro privado de educación infantil de primer ciclo ante la Generalitat Valenciana, lo que significa que atiende a niños de 0 a 3 años. La entidad titular es Escuela Infantil Ciudad Jardín, SL, sin régimen de concierto según el registro.

No hay constancia oficial de datos como comedor propio, horario ampliado o programas bilingües, ya que el registro autonómico no recoge esta información para centros privados. Por eso esta ficha se limita a los datos confirmados: ubicación, tipo de centro y titularidad, evitando cualquier afirmación que no pueda respaldarse con la fuente oficial.

